import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { CEProductCustomizationForm } from './CEProductCustomizationForm.jsx';

const element = document.getElementById('product-customization-form-react');
const storeName = element.getAttribute('data-store-name') || 'shared';
const watchStoreChanges = element.getAttribute('data-watch-store-changes') === 'true';
const country = element.getAttribute('data-country');
const language = element.getAttribute('data-language');
const market = element.getAttribute('data-market');

createRoot(element).render(
  <StrictMode>
    <CEProductCustomizationForm customizationHookConfig={{ storeName, watchStoreChanges, country, language, market }} />
  </StrictMode>,
);
